"use client"

import * as React from "react"
import { useReducedMotion } from "motion/react"
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  Cell,
  Line,
  LineChart,
  XAxis,
  YAxis,
} from "recharts"

import { cn } from "@/lib/utils"
import {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  type ChartConfig,
} from "@/components/ui/chart"
import {
  conventionClass,
  formatStat,
  toneColor,
  trendOf,
  type DataConvention,
  type DataTone,
  type StatFormatOptions,
} from "@/registry/lib/data-display"

import {
  MiniDonut,
  type MiniDonutProps,
  type MiniDonutSegment,
} from "./mini-donut"
import { MiniRing, type MiniRingProps } from "./mini-ring"

/** 数据点：纯数字，或带标签的 `{ label, value }`（标签用于横轴与提示框）。 */
type MiniChartDatum = number | { label?: string; value: number }

type MiniChartType = "bar" | "line" | "area" | "step"

type MiniChartProps = Omit<React.ComponentProps<"div">, "children"> & {
  /** 数据点，按顺序排列 */
  data: MiniChartDatum[]
  /**
   * 图形：`bar` 柱、`line` 折线、`area` 面积、`step` 阶梯线
   * @default "area"
   */
  type?: MiniChartType
  /**
   * 色调。`"trend"` 按首尾两点的涨跌自动取涨色或跌色（随 `convention` 变化）
   * @default "primary"
   */
  tone?: DataTone | "trend"
  /** 涨跌配色约定，仅 `tone="trend"` 时有用；不设置时沿用外层 */
  convention?: DataConvention
  /**
   * 显示横轴（11px 的极简刻度，只保留首尾与间隔均匀的标签）
   * @default false
   */
  showAxis?: boolean
  /** 横轴刻度文字的格式化，参数是数据点的 `label` */
  tickFormatter?: (label: string, index: number) => string
  /**
   * 悬停提示框
   * @default true
   */
  showTooltip?: boolean
  /** 提示框里数值的格式 */
  format?: StatFormatOptions
  /**
   * 提示框里的系列名
   * @default "数值"
   */
  seriesLabel?: string
  /** 柱图里强调的那一根：下标，`"last"` 最后一根，`"max"` 最大值；其余柱变淡 */
  highlight?: number | "last" | "max"
  /**
   * 柱图每根柱的底槽（淡色背景），像进度槽一样表示满值
   * @default false
   */
  track?: boolean
  /**
   * 线宽，仅折线、面积与阶梯线
   * @default 2
   */
  strokeWidth?: number
  /** 读屏名称，描述这张图表示什么 */
  label?: string
}

const AXIS_TICK = { fontSize: 11, fill: "var(--muted-foreground)" } as const

/** 极简迷你图：没有网格、没有纵轴，适合放进统计卡片；高度用 `className` 控制（默认 `h-16`）。 */
function MiniChart({
  className,
  data,
  type = "area",
  tone = "primary",
  convention,
  showAxis = false,
  tickFormatter,
  showTooltip = true,
  format,
  seriesLabel = "数值",
  highlight,
  track = false,
  strokeWidth = 2,
  label,
  ...props
}: MiniChartProps) {
  const reduced = useReducedMotion()
  const gradientId = React.useId().replaceAll(":", "")
  const points = data.map((datum, index) =>
    typeof datum === "number"
      ? { label: String(index + 1), value: datum }
      : { label: datum.label ?? String(index + 1), value: datum.value },
  )
  const first = points[0]?.value ?? 0
  const last = points.at(-1)?.value ?? 0
  const resolved: DataTone =
    tone === "trend"
      ? ({ up: "up", down: "down", flat: "muted" } as const)[
          trendOf(last - first)
        ]
      : tone
  const config = {
    value: { label: seriesLabel, color: toneColor(resolved) },
  } satisfies ChartConfig
  const focus =
    highlight === "last"
      ? points.length - 1
      : highlight === "max"
        ? points.findIndex(
            (point) => point.value === Math.max(...points.map((p) => p.value)),
          )
        : highlight

  const margin = { top: 4, right: 2, bottom: 0, left: 2 }
  const active = !reduced
  const axis = showAxis ? (
    <XAxis
      dataKey="label"
      tickLine={false}
      axisLine={false}
      tickMargin={6}
      minTickGap={12}
      interval="preserveStartEnd"
      tick={AXIS_TICK}
      tickFormatter={tickFormatter}
    />
  ) : (
    <XAxis dataKey="label" hide />
  )
  const tooltip = showTooltip ? (
    <ChartTooltip
      cursor={false}
      content={
        <ChartTooltipContent
          className="min-w-28 shadow-sm"
          formatter={(value) => (
            <>
              <span
                aria-hidden="true"
                className="size-2 shrink-0 rounded-[2px]"
                style={{ backgroundColor: toneColor(resolved) }}
              />
              <span className="text-muted-foreground">{seriesLabel}</span>
              <span className="ml-auto font-mono font-medium text-foreground tabular-nums">
                {formatStat(Number(value), format)}
              </span>
            </>
          )}
        />
      }
    />
  ) : null
  const color = "var(--color-value)"

  return (
    <ChartContainer
      data-slot="mini-chart"
      data-type={type}
      role="img"
      aria-label={label}
      config={config}
      initialDimension={{ width: 160, height: 64 }}
      className={cn(
        "aspect-auto h-16 w-full justify-start",
        conventionClass(convention),
        className,
      )}
      {...props}
    >
      {type === "bar" ? (
        <BarChart data={points} margin={margin} barCategoryGap="22%">
          {axis}
          <YAxis hide domain={[0, "dataMax"]} />
          {tooltip}
          <Bar
            dataKey="value"
            fill={color}
            radius={[3, 3, 0, 0]}
            maxBarSize={14}
            background={track ? { fill: "var(--muted)", radius: 3 } : undefined}
            isAnimationActive={active}
            animationDuration={600}
          >
            {points.map((point, index) => (
              <Cell
                key={index}
                fill={color}
                fillOpacity={focus === undefined || focus === index ? 1 : 0.28}
              />
            ))}
          </Bar>
        </BarChart>
      ) : type === "area" ? (
        <AreaChart data={points} margin={margin}>
          <defs>
            <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={color} stopOpacity={0.28} />
              <stop offset="100%" stopColor={color} stopOpacity={0} />
            </linearGradient>
          </defs>
          {axis}
          <YAxis hide domain={["dataMin", "dataMax"]} />
          {tooltip}
          <Area
            dataKey="value"
            type="monotone"
            stroke={color}
            strokeWidth={strokeWidth}
            fill={`url(#${gradientId})`}
            activeDot={{ r: 3, strokeWidth: 0 }}
            isAnimationActive={active}
            animationDuration={700}
          />
        </AreaChart>
      ) : (
        <LineChart data={points} margin={margin}>
          {axis}
          <YAxis hide domain={["dataMin", "dataMax"]} />
          {tooltip}
          <Line
            dataKey="value"
            type={type === "step" ? "stepAfter" : "monotone"}
            stroke={color}
            strokeWidth={strokeWidth}
            dot={false}
            activeDot={{ r: 3, strokeWidth: 0 }}
            isAnimationActive={active}
            animationDuration={700}
          />
        </LineChart>
      )}
    </ChartContainer>
  )
}

export { MiniChart, MiniDonut, MiniRing }
export type {
  MiniChartDatum,
  MiniChartProps,
  MiniChartType,
  MiniDonutProps,
  MiniDonutSegment,
  MiniRingProps,
}

"use client"

import * as React from "react"
import { motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import {
  formatStat,
  toneColor,
  type DataTone,
} from "@/registry/lib/data-display"

type MiniRingProps = Omit<React.ComponentProps<"div">, "children"> & {
  /** 当前值 */
  value: number
  /**
   * 满值
   * @default 100
   */
  max?: number
  /**
   * 进度弧的色调
   * @default "primary"
   */
  tone?: DataTone
  /**
   * 外径（像素）
   * @default 72
   */
  size?: number
  /**
   * 环的粗细，占外径的百分比
   * @default 10
   */
  thickness?: number
  /**
   * 圆弧的总角度：360 是整圆，270 是下方留口的仪表
   * @default 360
   */
  arc?: number
  /** 环中央的内容，默认是取整后的百分比 */
  children?: React.ReactNode
  /** 读屏名称 */
  label?: string
}

/**
 * 进度环：纯 SVG，比用图表库画一圈更轻也更清晰。
 * 进度弧从起点按弧线长度展开，系统开启「减少动态效果」时直接到位。
 */
function MiniRing({
  className,
  value,
  max = 100,
  tone = "primary",
  size = 72,
  thickness = 10,
  arc = 360,
  children,
  label,
  style,
  ...props
}: MiniRingProps) {
  const reduced = useReducedMotion()
  const ratio = max > 0 ? Math.min(1, Math.max(0, value / max)) : 0
  const sweep = Math.min(360, Math.max(30, arc)) / 360
  // 圆从 3 点钟方向顺时针画：整圆从 12 点开始，开口仪表让缺口落在正下方
  const rotation = sweep === 1 ? -90 : 90 + (360 * (1 - sweep)) / 2
  const radius = 50 - thickness / 2
  const common = {
    cx: 50,
    cy: 50,
    r: radius,
    fill: "none",
    strokeWidth: thickness,
    strokeLinecap: "round",
    transform: `rotate(${rotation} 50 50)`,
    pathLength: 1,
  } as const
  return (
    <div
      data-slot="mini-ring"
      role="meter"
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={max}
      aria-valuenow={value}
      className={cn(
        "relative flex shrink-0 items-center justify-center",
        className,
      )}
      style={{ width: size, height: size, ...style }}
      {...props}
    >
      <svg
        viewBox="0 0 100 100"
        aria-hidden="true"
        className="absolute inset-0 size-full"
      >
        <circle
          {...common}
          stroke="var(--edge)"
          strokeDasharray={`${sweep} 1`}
        />
        <motion.circle
          {...common}
          stroke={toneColor(tone)}
          initial={{ pathLength: 0 }}
          animate={{ pathLength: ratio * sweep }}
          transition={{ duration: reduced ? 0 : 0.9, ease: [0.22, 1, 0.36, 1] }}
        />
      </svg>
      <div
        data-slot="mini-ring-content"
        className="relative flex flex-col items-center text-center leading-tight tabular-nums"
      >
        {children ?? (
          <span className="text-sm font-semibold">
            {formatStat(ratio * 100, { style: "percent", digits: 0 })}
          </span>
        )}
      </div>
    </div>
  )
}

export { MiniRing }
export type { MiniRingProps }

"use client"

import * as React from "react"
import { useReducedMotion } from "motion/react"
import { Pie, PieChart } from "recharts"

import { cn } from "@/lib/utils"
import {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  type ChartConfig,
} from "@/components/ui/chart"
import {
  SERIES_TONES,
  formatStat,
  toneColor,
  type DataTone,
  type StatFormatOptions,
} from "@/registry/lib/data-display"

type MiniDonutSegment = {
  /** 分类名，同时是提示框里的名称 */
  label: string
  value: number
  /** 色调，不设置时按顺序取默认色板 */
  tone?: DataTone
}

type MiniDonutProps = Omit<React.ComponentProps<"div">, "children"> & {
  /** 分段数据 */
  segments: MiniDonutSegment[]
  /**
   * 外径（像素）
   * @default 96
   */
  size?: number
  /**
   * 环的粗细，占半径的百分比
   * @default 30
   */
  thickness?: number
  /** 悬停提示框里数值的格式 */
  format?: StatFormatOptions
  /** 环中央的内容，如合计数字 */
  children?: React.ReactNode
  /** 读屏名称 */
  label?: string
}

/** 环形图：几个分类的占比，中央可放合计。分段之间留 2° 的缝。 */
function MiniDonut({
  className,
  segments,
  size = 96,
  thickness = 30,
  format,
  children,
  label,
  style,
  ...props
}: MiniDonutProps) {
  const reduced = useReducedMotion()
  const config: ChartConfig = {}
  const data = segments.map((segment, index) => {
    const color = toneColor(
      segment.tone ?? SERIES_TONES[index % SERIES_TONES.length],
    )
    config[segment.label] = { label: segment.label, color }
    return { label: segment.label, value: segment.value, fill: color }
  })
  return (
    <div
      data-slot="mini-donut"
      role="img"
      aria-label={label}
      className={cn("relative shrink-0", className)}
      style={{ width: size, height: size, ...style }}
      {...props}
    >
      <ChartContainer
        config={config}
        initialDimension={{ width: size, height: size }}
        className="aspect-auto size-full"
      >
        <PieChart margin={{ top: 0, right: 0, bottom: 0, left: 0 }}>
          <ChartTooltip
            cursor={false}
            content={
              <ChartTooltipContent
                hideLabel
                nameKey="label"
                className="min-w-28 shadow-sm"
                formatter={(value, name, item) => (
                  <>
                    <span
                      aria-hidden="true"
                      className="size-2 shrink-0 rounded-[2px]"
                      style={{ backgroundColor: item.payload?.fill }}
                    />
                    <span className="text-muted-foreground">{name}</span>
                    <span className="ml-auto font-mono font-medium text-foreground tabular-nums">
                      {formatStat(Number(value), format)}
                    </span>
                  </>
                )}
              />
            }
          />
          <Pie
            data={data}
            dataKey="value"
            nameKey="label"
            innerRadius={`${100 - thickness}%`}
            outerRadius="100%"
            paddingAngle={2}
            cornerRadius={3}
            strokeWidth={0}
            isAnimationActive={!reduced}
            animationDuration={700}
          />
        </PieChart>
      </ChartContainer>
      {children ? (
        <div
          data-slot="mini-donut-content"
          className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center text-center leading-tight tabular-nums"
        >
          {children}
        </div>
      ) : null}
    </div>
  )
}

export { MiniDonut }
export type { MiniDonutProps, MiniDonutSegment }

/**
 * 数据展示共用工具：涨跌配色约定、色调、数字与日期格式化。
 * stat-card、mini-chart、chart-card 三个条目共用这一份，所以涨跌色、数字格式只在这里定义。
 */

/**
 * 涨跌配色约定：
 * - `intl`（默认）：绿涨红跌；
 * - `cn`：红涨绿跌，国内行情软件的习惯。
 */
type DataConvention = "intl" | "cn"

// 约定只改写 `--stat-up` / `--stat-down` 两个 CSS 变量。变量沿 DOM 向下继承，
// 所以给整块看板的外层设一次 `convention`，里面所有涨跌色（包括图表里的 SVG）都跟着变，
// 不需要 context，服务端组件也能用。没有设置时回落到默认的绿涨红跌。
const CONVENTION_CLASSES: Record<DataConvention, string> = {
  intl: "[--stat-up:var(--flow-green,var(--primary))] [--stat-down:var(--flow-rose,var(--destructive))]",
  cn: "[--stat-up:var(--flow-rose,var(--destructive))] [--stat-down:var(--flow-green,var(--primary))]",
}

/** 把 `convention` 换成要加到根元素上的类名；不传返回 `undefined`，沿用外层的约定。 */
function conventionClass(convention?: DataConvention) {
  return convention ? CONVENTION_CLASSES[convention] : undefined
}

type Trend = "up" | "down" | "flat"

function trendOf(value: number): Trend {
  return value > 0 ? "up" : value < 0 ? "down" : "flat"
}

/** 涨跌文字色（Tailwind 只认完整类名，所以三种写全）。 */
const TREND_TEXT: Record<Trend, string> = {
  up: "text-[color:var(--stat-up,var(--flow-green,var(--primary)))]",
  down: "text-[color:var(--stat-down,var(--flow-rose,var(--destructive)))]",
  flat: "text-muted-foreground",
}

/**
 * 内置色调：
 * - `primary`、`foreground`、`muted`、`destructive` 直接引用主题变量，跟随颜色主题；
 * - `blue` 等多彩色调引用 `--flow-*` 变量，没有安装时回落到主题强调色；
 * - `chart-1` … `chart-5` 引用主题的图表色板；
 * - `up` / `down` 是涨跌色，随 `convention` 变化。
 */
type DataToneName =
  | "primary"
  | "foreground"
  | "muted"
  | "destructive"
  | "blue"
  | "green"
  | "amber"
  | "rose"
  | "violet"
  | "cyan"
  | "chart-1"
  | "chart-2"
  | "chart-3"
  | "chart-4"
  | "chart-5"
  | "up"
  | "down"

/** 色调：内置名，或任意 CSS 颜色（`"var(--brand)"`、`"oklch(0.7 0.2 150)"` 都可以）。 */
type DataTone = DataToneName | (string & {})

const TONES: Record<DataToneName, string> = {
  primary: "var(--primary)",
  foreground: "var(--foreground)",
  muted: "var(--muted-foreground)",
  destructive: "var(--destructive)",
  blue: "var(--flow-blue, var(--primary))",
  green: "var(--flow-green, var(--primary))",
  amber: "var(--flow-amber, var(--primary))",
  rose: "var(--flow-rose, var(--destructive))",
  violet: "var(--flow-violet, var(--primary))",
  cyan: "var(--flow-cyan, var(--primary))",
  "chart-1": "var(--chart-1)",
  "chart-2": "var(--chart-2)",
  "chart-3": "var(--chart-3)",
  "chart-4": "var(--chart-4)",
  "chart-5": "var(--chart-5)",
  up: "var(--stat-up, var(--flow-green, var(--primary)))",
  down: "var(--stat-down, var(--flow-rose, var(--destructive)))",
}

/** 把色调换成可直接用于 `fill` / `stroke` / `color` 的 CSS 颜色。 */
function toneColor(tone: DataTone): string {
  return Object.hasOwn(TONES, tone) ? TONES[tone as DataToneName] : tone
}

/** 多序列图表默认的色调轮换：第一条跟随主题强调色，其余取多彩色调。 */
const SERIES_TONES: DataTone[] = [
  "primary",
  "blue",
  "amber",
  "violet",
  "cyan",
  "green",
  "rose",
]

type StatFormatOptions = {
  /**
   * 数字样式：`number` 普通数字，`percent` 百分比（传入的 12.5 表示 12.5%），`currency` 货币
   * @default "number"
   */
  style?: "number" | "percent" | "currency"
  /**
   * BCP 47 区域标识；`zh-CN` 压缩成「万 / 亿」，`en` 压缩成 K / M / B
   * @default "zh-CN"
   */
  locale?: string
  /**
   * 压缩大数（1.2万、3.4亿）；百分比不压缩
   * @default true
   */
  compact?: boolean
  /**
   * 货币代码，仅 `style="currency"` 生效；人民币显示 ¥
   * @default "CNY"
   */
  currency?: string
  /**
   * 最多保留的小数位
   * @default 1（压缩与百分比），2（普通数字与货币）
   */
  digits?: number
  /**
   * 正数前加 `+`（零不加），用于涨跌幅
   * @default false
   */
  sign?: boolean
}

const formatters = new Map<string, Intl.NumberFormat>()

/**
 * 格式化统计数字，默认 `zh-CN` 压缩：`12480` → `1.2万`，`345000000` → `3.5亿`；
 * `locale: "en"` 时为 `12K`、`345M`。同参数的 `Intl.NumberFormat` 会被缓存复用。
 */
function formatStat(value: number, options: StatFormatOptions = {}): string {
  const {
    style = "number",
    locale = "zh-CN",
    compact = style !== "percent",
    currency = "CNY",
    sign = false,
  } = options
  const digits = options.digits ?? (compact || style === "percent" ? 1 : 2)
  const key = [style, locale, compact, currency, digits, sign].join("|")
  let formatter = formatters.get(key)
  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, {
      style: style === "number" ? "decimal" : style,
      currency: style === "currency" ? currency : undefined,
      currencyDisplay: style === "currency" ? "narrowSymbol" : undefined,
      notation: compact && style !== "percent" ? "compact" : "standard",
      maximumFractionDigits: digits,
      signDisplay: sign ? "exceptZero" : "auto",
    })
    formatters.set(key, formatter)
  }
  return formatter.format(style === "percent" ? value / 100 : value)
}

type DayStyle = "long" | "short" | "weekday"

const dayFormatters = new Map<string, Intl.DateTimeFormat>()

/**
 * 格式化日期轴文字：`long` → `2月14日`，`short` → `02/14`，`weekday` → `一`（单字星期）。
 * 日期按 UTC 解析与输出，`"2026-02-14"` 这类字符串在任何时区、任何环境下结果一致，不会引起水合差异。
 */
function formatDay(
  input: string | number | Date,
  style: DayStyle = "long",
  locale = "zh-CN",
): string {
  const key = `${style}|${locale}`
  let formatter = dayFormatters.get(key)
  if (!formatter) {
    const options: Intl.DateTimeFormatOptions =
      style === "weekday"
        ? { weekday: "narrow" }
        : style === "short"
          ? { month: "2-digit", day: "2-digit" }
          : { month: "long", day: "numeric" }
    formatter = new Intl.DateTimeFormat(locale, { ...options, timeZone: "UTC" })
    dayFormatters.set(key, formatter)
  }
  return formatter.format(new Date(input))
}

export {
  TREND_TEXT,
  SERIES_TONES,
  conventionClass,
  formatDay,
  formatStat,
  toneColor,
  trendOf,
}
export type {
  DataConvention,
  DataTone,
  DataToneName,
  DayStyle,
  StatFormatOptions,
  Trend,
}
